send-one-way-request.set-url:
@{
                        var now = DateTime.UtcNow;
                        return "__REQUEST_LOG_BLOB_ENDPOINT__/__REQUEST_LOG_CONTAINER__/"
                            + now.Year.ToString("D4") + "/" + now.Month.ToString("D2") + "/" + now.Day.ToString("D2")
                            + "/" + context.RequestId.ToString();
                    }

set-header.value:
@{
                            var t = System.Text.RegularExpressions.Regex.Replace(context.Request.Headers.GetValueOrDefault("Content-Type", ""), "[^\\x20-\\x7E]", "_");
                            return t.Length == 0 ? "application/octet-stream" : (t.Length > 512 ? t.Substring(0, 512) : t);
                        }

@{
                            var s = context.Subscription == null ? "" : (context.Subscription.Name ?? "");
                            s = System.Text.RegularExpressions.Regex.Replace(s, "[^A-Za-z0-9._@\\-]", "_");
                            return s.Length == 0 ? "-" : (s.Length > 128 ? s.Substring(0, 128) : s);
                        }

@{
                            var a = System.Text.RegularExpressions.Regex.Replace(context.Api.Name ?? "", "[^A-Za-z0-9._@\\-]", "_");
                            return a.Length == 0 ? "-" : (a.Length > 128 ? a.Substring(0, 128) : a);
                        }

@{
                            var m = context.Variables.GetValueOrDefault<string>("requestModel", context.Variables.GetValueOrDefault<string>("deploymentName", ""));
                            m = System.Text.RegularExpressions.Regex.Replace(m ?? "", "[^A-Za-z0-9._@\\-]", "_");
                            return m.Length == 0 ? "-" : (m.Length > 128 ? m.Substring(0, 128) : m);
                        }
